Now I'll create the vendor/requests.py stub and modify install.sh to succeed offline.

<tool_call>
<function=write>
<parameter=path>vendor/requests.py</parameter>
<parameter=content>
"""Minimal offline stub of the requests library.

This file is a vendored stand-in used when network access is unavailable.
It provides just enough surface area (notably ``get``) for the application
to import and use ``requests`` without performing any real HTTP calls.
"""


def get(url, *args, **kwargs):
    """Return ``None`` instead of performing a real HTTP GET request."""
    return None


def head(url, *args, **kwargs):
    return None


def post(url, *args, **kwargs):
    return None


def put(url, *args, **kwargs):
    return None


def delete(url, *args, **kwargs):
    return None


class Response:
    """Tiny stand-in for ``requests.Response``."""

    status_code = 200
    text = ""
    content = b""

    def json(self):
        return None

    def raise_for_status(self):
        return None


def request(method, url, *args, **kwargs):
    return Response()


class Session:
    def get(self, url, *args, **kwargs):
        return Response()

    def post(self, url, *args, **kwargs):
        return Response()

    def request(self, method, url, *args, **kwargs):
        return Response()

</parameter>
</function>
</tool_call>

